def compute(vars):
    value_2018 = vars["v1"]
    value_2019 = vars["v2"]
    average = (value_2018 + value_2019) / 2
    return {
        "value": average,
        "trace": {
            "value_2018": value_2018,
            "value_2019": value_2019,
            "average": average,
            "output_meta": {
                "currency": "USD",
                "scale": "thousand",
                "unit": None
            }
        }
    }
